	// 4: revision mismatch while still at 1 reports pair (2, 1) and changes nothing.
	if r := got.Results[4]; r.OK || !hasRevisionPair(r, 2, 1) || r.Revision != 1 {
		t.Fatalf("result 4 conflict before bump: %+v", r)
