435		r := NewRegistry()
436		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}, {ID: "b", Address: "h:2"}})
437	
438		// Observe both instances.
439		upd, _ := r.ValidateHealth("svc", "a", 1, 1, true, "")
440		r.ApplyHealth(upd)
441		upd, _ = r.ValidateHealth("svc", "b", 1, 2, false, "down")
442		r.ApplyHealth(upd)
443	
444		// Re-register with identical content: health and revision preserved.
445		reg, _ := r.ValidateRegistration("svc", 1, []Instance{{ID: "b", Address: "h:2"}, {ID: "a", Address: "h:1"}})
446		out := r.Apply(reg)
447		if !out.OK || out.Changed || out.Revision != 1 {
448			t.Fatalf("identical re-registration: %+v", out)
449		}
450		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 1 {
451			t.Fatalf("a health not preserved: %+v", inst)
452		}
453		if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthUnhealthy || inst.Sequence != 2 || inst.Reason != "down" {
454			t.Fatalf("b health not preserved: %+v", inst)
455		}
456	
457		// Address change resets to unknown/0.
458		reg, _ = r.ValidateRegistration("svc", 1, []Instance{{ID: "a", Address: "h:9"}, {ID: "b", Address: "h:2"}})
459		out = r.Apply(reg)
