126		// just after i2 (the last actually rotated id) and wraps to i1 — not i2
127		// again, which a rebuilt/reset state would have forced.
128		assertPick(t, selected(t, r, "svc", int64(limit)), "i1", "h1:1", 11)
129	}
130	
131	// TestRegistryRevisionLimitIdenticalContentSucceeds locks the other half: at
132	// the cap a matching submission whose normalized content is unchanged is a
133	// normal success with no changed field and an unchanged revision. This covers
134	// a plain duplicate, a pure reorder, field trimming, and an already-empty list
135	// resubmitted as an empty array.
136	func TestRegistryRevisionLimitIdenticalContentSucceeds(t *testing.T) {
137		const limit = math.MaxInt
138	
139		r := NewRegistry()
140		seedAtRevision(t, r, "svc", limit, []Instance{
141			{ID: "i1", Address: "h1:1"},
142			{ID: "i2", Address: "h2:2"},
143		})
144		markHealth(t, r, "svc", "i1", int64(limit), 11, true, "")
145	
146		identical := [][]Instance{
147			// Plain duplicate.
148			{{ID: "i1", Address: "h1:1"}, {ID: "i2", Address: "h2:2"}},
149			// Pure reorder: content unchanged by the existing rule.
150			{{ID: "i2", Address: "h2:2"}, {ID: "i1", Address: "h1:1"}},
151			// Whitespace padding around the service name, ids and addresses is
152			// trimmed during validation, so the normalized content is identical.
153			{{ID: " i1 ", Address: "  h1:1  "}, {ID: "\ti2\t", Address: " h2:2 "}},
154		}
155		for i, list := range identical {
156			reg, err := r.ValidateRegistration("  svc  ", int64(limit), list)
157			if err != nil {
158				t.Fatalf("identical case %d must validate: %v", i, err)
159			}
160			if out := r.Apply(reg); !out.OK || out.Changed || out.Revision != limit {
161				t.Fatalf("identical case %d must succeed without a change at the cap: %+v", i, out)
162			}
163			// Health survives the no-op replacement, and no revision comparison
164			// fields appear on the success.
165			if inst := instanceHealth(t, r, "svc", "i1"); inst.Health != HealthHealthy || inst.Sequence != 11 {
166				t.Fatalf("identical case %d must keep health: %+v", i, inst)
167			}
168		}
169	
170		// An already-empty list resubmitted as [] is content-unchanged too.
171		empty := NewRegistry()
172		seedAtRevision(t, empty, "ghost", limit, nil)
173		reg, err := empty.ValidateRegistration("ghost", int64(limit), nil)
174		if err != nil {
175			t.Fatalf("empty resubmission must validate: %v", err)
176		}
177		if out := reg; out.Service != "ghost" || out.Revision != limit {
178			t.Fatalf("validated empty resubmission: %+v", out)
179		}
180		if out := empty.Apply(reg); !out.OK || out.Changed || out.Revision != limit {
181			t.Fatalf("empty resubmission at the cap must succeed unchanged: %+v", out)
182		}
183		views := empty.Snapshot()
184		if len(views) != 1 || views[0].Revision != limit || len(views[0].Instances) != 0 {
185			t.Fatalf("empty service view: %+v", views)
186		}
187	}
188	
189	// TestRegistryRevisionLimitMinusOneStillIncrements locks that the cap does not
190	// clamp ordinary replacements early: a real replacement at max-1 succeeds and
191	// increments exactly to max, with unchanged-id/address instances keeping their
192	// health and changed/new instances resetting to unknown/0.
193	func TestRegistryRevisionLimitMinusOneStillIncrements(t *testing.T) {
194		const limit = math.MaxInt
195	
196		r := NewRegistry()
197		seedAtRevision(t, r, "svc", limit-1, []Instance{
198			{ID: "i1", Address: "h1:1"},
199			{ID: "i2", Address: "h2:2"},
200		})
201		markHealth(t, r, "svc", "i1", int64(limit-1), 11, true, "")
202		markHealth(t, r, "svc", "i2", int64(limit-1), 22, false, "磁盘故障")
203	
204		// i1 keeps id and address; i2 changes address (health resets); i3 is new
205		// (unknown/0). The revision climbs exactly from max-1 to max.
206		reg, err := r.ValidateRegistration("svc", int64(limit-1), []Instance{
207			{ID: "i1", Address: "h1:1"},
208			{ID: "i2", Address: "h9:9"},
209			{ID: "i3", Address: "h3:3"},
210		})
211		if err != nil {
212			t.Fatalf("replacement at max-1 must validate: %v", err)
213		}
214		if out := r.Apply(reg); !out.OK || !out.Changed || out.Revision != limit {
215			t.Fatalf("replacement at max-1 must increment to the limit: %+v", out)
216		}
217		if inst := instanceHealth(t, r, "svc", "i1"); inst.Address != "h1:1" ||
218			inst.Health != HealthHealthy || inst.Sequence != 11 {
219			t.Fatalf("i1 must keep its health record into the limit: %+v", inst)
220		}
221		if inst := instanceHealth(t, r, "svc", "i2"); inst.Address != "h9:9" ||
222			inst.Health != HealthUnknown || inst.Sequence != 0 || inst.Reason != "" {
223			t.Fatalf("i2 must reset after the address change: %+v", inst)
224		}
225		if inst := instanceHealth(t, r, "svc", "i3"); inst.Health != HealthUnknown || inst.Sequence != 0 {
226			t.Fatalf("i3 must start unknown/0: %+v", inst)
227		}
228	
229		// Now at the cap: one further real change (removing i3) is refused, and
230		// health at the new revision keeps working on the surviving instances.
231		reg, _ = r.ValidateRegistration("svc", int64(limit), []Instance{
232			{ID: "i1", Address: "h1:1"},
233			{ID: "i2", Address: "h9:9"},
234		})
235		if out := r.Apply(reg); out.OK || out.Kind != OutcomeInvalid || out.Revision != limit {
236			t.Fatalf("further change at the limit must be refused: %+v", out)
237		}
238		// A health report at revision max is accepted normally (it never bumps the
239		// registration revision) and makes the address-changed i2 eligible.
240		markHealth(t, r, "svc", "i2", int64(limit), 1, true, "")
241		assertPick(t, trySelect(t, r, "svc", int64(limit)), "i1", "h1:1", 11)
242		assertPick(t, trySelect(t, r, "svc", int64(limit)), "i2", "h9:9", 1)
243	}
244	
245	// TestRegistryRevisionLimitErrorPrecedence locks that the limit rule sits after
246	// the existing checks: invalid content is still invalid as the field rule, and
247	// a fully valid list with a mismatched expectedRevision is still a conflict
248	// carrying the comparison pair — neither is replaced by the limit error.
249	func TestRegistryRevisionLimitErrorPrecedence(t *testing.T) {
250		const limit = math.MaxInt
251	
252		r := NewRegistry()
253		seedAtRevision(t, r, "svc", limit, []Instance{{ID: "i1", Address: "h1:1"}})
254	
255		// Invalid content (bad address) wins as the field-level invalid reason even
256		// though accepting the change would also hit the cap.
257		reg, err := r.ValidateRegistration("svc", int64(limit), []Instance{{ID: "i1", Address: "bad-address"}})
258		if err == nil {
259			t.Fatalf("bad address must fail validation")
260		}
261		if !strings.Contains(err.Error(), "host:port") {
262			t.Fatalf("want the address reason, got %q", err.Error())
263		}
264	
265		// A valid list at the cap with a mismatched expectedRevision is a normal
266		// revision conflict with expected/actual and no limit wording; nothing is
267		// applied.
268		reg, err = r.ValidateRegistration("svc", int64(limit-1), []Instance{{ID: "i2", Address: "h2:2"}})
269		if err != nil {
270			t.Fatalf("valid list must validate: %v", err)
271		}
272		out := r.Apply(reg)
273		if out.OK || out.Kind != OutcomeConflict || !out.RevisionMismatch ||
274			out.Expected != limit-1 || out.Actual != limit || out.Revision != limit {
275			t.Fatalf("revision mismatch at the cap must stay a conflict: %+v", out)
276		}
277		if strings.Contains(out.Reason, "limit") {
278			t.Fatalf("conflict reason must not mention the limit: %q", out.Reason)
279		}
280		if inst := instanceHealth(t, r, "svc", "i1"); inst.Address != "h1:1" {
281			t.Fatalf("conflict at the cap must not replace the list: %+v", inst)
282		}
283	}
284	
285	// TestRegistryRevisionLimitPostRejectionOperations verifies that after a
286	// refused change the service keeps working under the existing rules at the cap:
287	// health reports, rotation selection, session reuse and release, and stale
288	// revisions all behave normally.
289	func TestRegistryRevisionLimitPostRejectionOperations(t *testing.T) {
290		const limit = math.MaxInt
291	
292		r := NewRegistry()
293		seedAtRevision(t, r, "svc", limit, []Instance{
294			{ID: "i1", Address: "h1:1"},
295			{ID: "i2", Address: "h2:2"},
296		})
297		markHealth(t, r, "svc", "i1", int64(limit), 11, true, "")
298		markHealth(t, r, "svc", "i2", int64(limit), 22, true, "")
299	
300		// Bind a session and advance the shared cursor before the refusal.
301		assertPick(t, selectSession(t, r, "svc", int64(limit), "k"), "i1", "h1:1", 11)
302		assertPick(t, selected(t, r, "svc", int64(limit)), "i2", "h2:2", 22)
303	
304		// Refuse a real change at the cap (address change for i1).
305		reg, err := r.ValidateRegistration("svc", int64(limit), []Instance{
306			{ID: "i1", Address: "h9:9"}, {ID: "i2", Address: "h2:2"},
307		})
308		if err != nil {
309			t.Fatalf("valid list must validate: %v", err)
310		}
311		assertInvalidAtLimit(t, r.Apply(reg), limit)
312	
313		// A stale revision is still an ordinary conflict carrying the pair.
314		upd, _ := r.ValidateHealth("svc", "i1", int64(limit-1), 12, true, "")
315		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeConflict ||
316			!out.RevisionMismatch || out.Expected != limit-1 || out.Actual != limit || out.Revision != limit {
317			t.Fatalf("stale-revision health at the cap: %+v", out)
318		}
319		// A matching health report is accepted normally.
320		markHealth(t, r, "svc", "i1", int64(limit), 12, true, "")
321	
322		// The bound session still reuses i1 with the fresh sequence, and the
323		// rotation cursor is still just after i2: the next plain select wraps to
324		// i1 rather than repeating i2.
325		assertPick(t, selectSession(t, r, "svc", int64(limit), "k"), "i1", "h1:1", 12)
326		assertPick(t, selected(t, r, "svc", int64(limit)), "i1", "h1:1", 12)
327	
328		// Releasing the session succeeds with changed, chooses no target, and moves
329		// neither the revision nor the cursor; the key's next selection rotates from
330		// the current position (after i1) to i2.
331		rel, err := r.ValidateSessionRelease("svc", int64(limit), strPtr("k"))
332		if err != nil {
333			t.Fatalf("release validation: %v", err)
334		}
335		relOut := r.ReleaseSession(rel)
336		if !relOut.OK || !relOut.Changed || relOut.Revision != limit {
337			t.Fatalf("release at the cap: %+v", relOut)
338		}
339		assertPick(t, selectSession(t, r, "svc", int64(limit), "k"), "i2", "h2:2", 22)
340	
341		// Releasing a key that was never bound still succeeds without changed.
342		rel, _ = r.ValidateSessionRelease("svc", int64(limit), strPtr("never-bound"))
343		if out := r.ReleaseSession(rel); !out.OK || out.Changed || out.Revision != limit {
344			t.Fatalf("unbound-key release at the cap: %+v", out)
345		}
346	
347		// The service snapshot still reports the cap and the original addresses.
348		views := r.Snapshot()
349		if len(views) != 1 || views[0].Revision != limit || len(views[0].Instances) != 2 {
350			t.Fatalf("snapshot after cap operations: %+v", views)
351		}
352	}
