// revisionGateVerdict is the single registration-revision judgment shared by
// every request kind — registration replacement, health observations, target
// selection and session release. Looking a service up and comparing its
// current revision with the submitted expectedRevision happens only here, so
// the same comparison can never drift apart between operations. Each kind
// keeps its own success conditions and failure results: a verdict only
// classifies the revision situation; the caller maps it onto its own outcome.
//
// The classification, for a service looked up once at the time the item is
// handled (an unknown service is at revision 0):
//
//   - revisionGateConflict: expected != actual. Every request kind reports the
//     same conflict for it — including a register request for an unknown
//     service with a non-zero expectedRevision — carrying the submitted
//     expectedRevision and the actual revision as a comparable pair. Each side
//     may legitimately be 0, so callers serialize both explicitly.
//   - revisionGateCreate: expected == actual == 0 and the service is unknown.
//     Only registration may create the service (it starts at revision 1); the
//     other kinds map the same situation onto their not_found result.
//   - revisionGateProceed: expected == actual on a registered service (whose
//     instance list may be empty — an emptied service still exists and is
//     compared by its real revision). The caller owns the remaining,
//     operation-specific rules.
type revisionGateVerdict int

const (
	revisionGateConflict revisionGateVerdict = iota
	revisionGateCreate
	revisionGateProceed
)

// revisionGateFailure carries a non-passing registration-revision judgment.
// It carries no operation-specific fields: each operation maps it onto its
// own result so a missing instance, a missing healthy target and a
// same-sequence health-content conflict never get mixed together.
//
// mismatch is true only for the revision-mismatch conflict, whose expected and
// actual revisions are both real values (each side may legitimately be 0). It
// is false for the matching-revision not_found a non-register operation
// reports for an unknown service at expectedRevision 0, which reports no
// comparison.
type revisionGateFailure struct {
	verdict  revisionGateVerdict
	kind     OutcomeKind
	reason   string
	revision int // current revision (0 for an unknown service)
	expected int
	actual   int
	mismatch bool
}

// registerGateConflictReason is the conflict reason for a register request
// against an unknown service with a non-zero expectedRevision; register keeps
// its own wording while the comparison itself is the shared gate's.
func registerGateConflictReason(service string, expected int) string {
	return fmt.Sprintf("service %q does not exist yet; expected revision must be 0, got %d", service, expected)
}

// gateRevisionConflict assembles the shared conflict for a current revision
// that differs from the submitted expectedRevision. revision is the value
// current when the item is handled, never a revision a later request in the
// batch produces.
func gateRevisionConflict(service string, expected, revision int) *revisionGateFailure {
	return &revisionGateFailure{
		verdict:  revisionGateConflict,
		kind:     OutcomeConflict,
		reason:   fmt.Sprintf("service %q is at revision %d, not %d", service, revision, expected),
		revision: revision,
		expected: expected,
		actual:   revision,
		mismatch: true,
	}
}

// enterRevisionGate performs the one registration-revision judgment every
// request kind shares. Content validation has already happened by the time it
// runs, so an invalid field never reaches it. It looks the service up once (an
// unknown service is at revision 0) and compares revisions:
//
// A mismatch is a conflict carrying the request's expectedRevision and the
// actual revision, even when the service or the targeted instance is missing
// — both values are flagged so callers emit them even when one side is 0.
//
// With matching revisions an unknown service (necessarily at expectedRevision
// 0) yields revisionGateCreate: registration creates it at revision 1, while
// the other kinds turn it into their not_found result without a comparison.
// A registered service — including one whose instance list was emptied — is
// handed back so every operation compares it by its real revision rather than
// treating it as absent.
func (r *Registry) enterRevisionGate(service string, expected int) (*serviceState, *revisionGateFailure) {
	st, exists := r.services[service]
	actual := 0
	if exists {
		actual = st.revision
	}
	if expected != actual {
		return nil, gateRevisionConflict(service, expected, actual)
	}
	if !exists {
		return nil, &revisionGateFailure{
			verdict:  revisionGateCreate,
			kind:     OutcomeNotFound,
			reason:   fmt.Sprintf("service %q does not exist", service),
			revision: 0,
		}
	}
	return st, nil
}

// notFound turns the matching-revision unknown-service verdict into the
// operation-specific not_found failure (register never maps this verdict: it
// creates the service instead). The comparison fields stay zero so they are
// omitted exactly as each operation's own not_found result always has been.
func (f *revisionGateFailure) notFound() *revisionGateFailure {
	return &revisionGateFailure{
		verdict:  revisionGateCreate,
		kind:     OutcomeNotFound,
		reason:   f.reason,
		revision: 0,
	}
}

// asHealth maps the shared revision gate failure onto a health result. The
// operation-specific fields (instance id and the current sequence) stay zero so
// they remain omitted exactly as health's own revision failures always have.
func (f *revisionGateFailure) asHealth(service string) HealthOutcome {
	return HealthOutcome{
		Service:          service,
		OK:               false,
		Kind:             f.kind,
		Reason:           f.reason,
		Revision:         f.revision,
		Expected:         f.expected,
		Actual:           f.actual,
		RevisionMismatch: f.mismatch,
	}
}

